use std :: path :: { Path , PathBuf } ; use std :: sync :: Arc ; use anyhow :: Context ; use forge_app :: domain :: Skill ; use forge_app :: { EnvironmentInfra , FileInfoInfra , FileReaderInfra , Walker , WalkerInfra } ; use forge_domain :: SkillRepository ; use futures :: future :: join_all ; use gray_matter :: Matter ; use gray_matter :: engine :: YAML ; use serde :: Deserialize ; use forge_config :: ForgeConfig ; use forge_infra :: ForgeInfra ; use pretty_assertions :: assert_eq ; use super :: * ; # [doc = " Extracts metadata from the skill markdown content using YAML front matter"] # [doc = ""] # [doc = " Parses YAML front matter from the markdown content and extracts skill"] # [doc = " metadata. Expected format:"] # [doc = " ```markdown"] # [doc = " ---"] # [doc = " name: \"skill-name\""] # [doc = " description: \"Your description here\""] # [doc = " ---"] # [doc = " # Skill content..."] # [doc = " ```"] # [doc = ""] # [doc = " Returns a tuple of (name, description) where both are Option<String>."] fn extract_skill (path : & str , content : & str) -> Option < Skill > { let matter = Matter :: < YAML > :: new () ; let result = matter . parse :: < SkillMetadata > (content) ; result . ok () . and_then (| parsed | { let command = parsed . content ; parsed . data . and_then (| data | data . name . zip (data . description)) . map (| (name , description) | Skill :: new (name , command , description) . path (path)) }) }